def solve():
    n, k = map(int, input().split())
    stations = list(map(int, input().split()))

    # Create a set of all stations in the route
    station_set = set(stations)

    # Build a list of unique stations in order (left to right)
    unique_stations = []
    seen = set()
    for station in stations:
        if station not in seen:
            seen.add(station)
            unique_stations.append(station)

    # Create a dictionary to map station to its index in the sorted unique list
    station_to_index = {}
    for idx, station in enumerate(unique_stations):
        station_to_index[station] = idx

    # For each query, check if both a and b are in the route
    # and if a appears before b in the route (i.e., in the forward direction)
    for _ in range(k):
        a, b = map(int, input().split())

        if a not in station_set or b not in station_set:
            print("NO")
        else:
            # Find positions of a and b in the route (in order of appearance)
            a_pos = -1
            b_pos = -1
            for i, station in enumerate(stations):
                if station == a and a_pos == -1:
                    a_pos = i
                if station == b and b_pos == -1:
                    b_pos = i
                    break

            # If b is not found after a, then we cannot go from a to b
            # We only go forward, so we need to find a path where a comes before b
            # But we have to check if b appears after a in the sequence
            # Since the train goes only left to right, we can only travel from a to b
            # if a appears before b in the original route
            if a_pos == -1 or b_pos == -1:
                print("NO")
            else:
                # We can travel from a to b only if a appears before b in the route
                if a_pos < b_pos:
                    print("YES")
                else:
                    print("NO")

t = int(input())
for _ in range(t):
    solve()
